    /**
     * * `confirmed_flake` - CONFIRMED_FLAKE
     * * `suspected_regression` - SUSPECTED_REGRESSION
     * * `quarantined` - QUARANTINED
     */
    export type FlakyTestItemClassificationEnum = typeof FlakyTestItemClassificationEnum[keyof typeof FlakyTestItemClassificationEnum];


    export const FlakyTestItemClassificationEnum = {
      ConfirmedFlake: 'confirmed_flake',
      SuspectedRegression: 'suspected_regression',
      Quarantined: 'quarantined',
    } as const;

    export interface FlakyTestItem {
      /** Test runner that emitted this signal: 'pytest' or 'jest'.
       *
       * * `pytest` - PYTEST
       * * `jest` - JEST */
      runner: CITestRunnerEnum;
      /** Runner-specific stable test identity (the CI span name). This is a grouping key, not necessarily runnable; use `selector` to run or quarantine the test. */
      nodeid: string;
      /** Runnable pytest or Jest selector. Exact when the CI reporter emitted it; older pytest spans use a best-effort reconstruction from the nodeid. */
      selector: string;
      /** confirmed_flake: one commit both failed and passed the test (a re-run attempt went green, or an in-job retry recovered it), so it is provably nondeterministic. quarantined: a tolerated failure was recorded while it was masked. suspected_regression: only failures were recorded, which is absence of proof, not proof that it is a real break.
       *
       * * `confirmed_flake` - CONFIRMED_FLAKE
       * * `suspected_regression` - SUSPECTED_REGRESSION
       * * `quarantined` - QUARANTINED */
      classification: FlakyTestItemClassificationEnum;
      /** Runs where one commit both failed and passed the test: a 'Re-run failed jobs' attempt went green on the same commit, or an in-job pytest retry (tests hand-marked @pytest.mark.flaky(reruns=N)) recovered it. A pass in a different run is a different commit and never counts. */
      same_commit_recovery_run_count: number;
      /** Distinct CI runs whose recorded outcome was failed or error. A run counts once however many matrix legs it failed in. */
      failed_run_count: number;
      /** Distinct pull requests among the failed runs. Failures on master or unattributed branches carry no PR number and are excluded here (still in failed_run_count). */
      failed_pr_count: number;
      /** Failed runs on the default branch (master/main approximation): the 'matters right now' signal that a test is breaking the trunk, not just PR branches. */
      master_failed_run_count: number;
      /** Runs where the test recorded a tolerated failure while quarantined: already masked in CI, still failing. */
      quarantined_failed_run_count: number;
      /** Most recent failure, recovery, or quarantined-failure run for this test in the window. */
      last_signal_at: string;
    }

    export interface FlakyTestList {
      /** Tests worth acting on now, ranked by blast radius: master failures, then PRs hit, then runs. */
      items: FlakyTestItem[];
      /** True when more tests qualified than the cap; `items` is the highest-ranked `limit` rows. */
      truncated: boolean;
      /** Maximum number of tests returned in `items`. */
      limit: number;
    }

    /**
     * Fleet-wide tally of recent scout output — legacy `emit_signal` findings plus reports
     * authored/edited via the report channel. Backs the "Scout findings" callout so it renders
     * from one cheap query instead of the client walking the whole paginated runs window.
     */
    export interface FleetFindingsSummary {
      /** Total findings the fleet emitted in the window — the sum of each run's `emitted_count`, over the most recent 120 runs that produced output. */
      count: number;
      /** Number of distinct scouts (skills) that produced output in the window — emitted a finding, or authored/edited an inbox report that survives the 50-report cap (a report-only scout whose touched reports all fell outside the cap is not counted, matching the findings page's scout filter). */
      scout_count: number;
      /** Number of distinct inbox reports scouts authored via `emit_report`, deduped across runs, over the same most-recent-120-output-runs set as `count`, capped to the 50 most recently touched reports (the same slice the findings page lists). */
      authored_report_count: number;
      /** Number of distinct inbox reports scouts edited via `edit_report`, deduped across runs, over the same most-recent-120-output-runs set as `count`, capped to the 50 most recently touched reports (the same slice the findings page lists) and excluding reports also authored within that set (authoring supersedes an edit; a report whose authoring run falls outside the cap counts as edited). */
      edited_report_count: number;
      /** Number of scout runs created in the window, whether or not they produced output. Unlike the report tallies it is not capped, so it is the fleet's activity over the same span the output counts describe. */
      run_count: number;
      /**
         * ISO-8601 timestamp of the most recent output run (TaskRun completion, falling back to run creation), or null when nothing was produced in the window.
         * @nullable
         */
      latest_at: string | null;
    }

