    /**
     * A team-scoped definition of a custom account property — the attribute side of the model.
     *
     * Holds only the property's shape (name, display type, big-number flag). Per-account values are
     * stored separately, so this serializer never reads or writes account values.
     */
    export interface PatchedCustomPropertyDefinition {
      readonly id?: string;
      /**
         * Human-readable name of the custom property. Unique within the team.
         * @maxLength 400
         */
      name?: string;
      /**
         * Optional description of what the property represents.
         * @nullable
         */
      description?: string | null;
      /** How the property is interpreted and rendered: 'text', 'number', 'currency', 'percent', 'date', 'datetime', 'boolean', or 'select'.
       *
       * * `text` - text
       * * `number` - number
       * * `currency` - currency
       * * `percent` - percent
       * * `date` - date
       * * `datetime` - datetime
       * * `boolean` - boolean
       * * `select` - select */
      display_type?: CustomPropertyDisplayTypeEnum;
      /** What entity this property is attached to: 'account' (default), 'person', or 'group'. Person and group properties are populated from a warehouse schema and become usable like any other person/group property (feature flags, cohorts, insights).
       *
       * * `account` - account
       * * `person` - person
       * * `group` - group */
      target_type?: CustomPropertyDefinitionTargetTypeEnum;
      /**
         * For 'group' targets only: which group type (0-4) the property attaches to. Required when target_type is 'group'; must be omitted otherwise. Create-only.
         * @minimum 0
         * @maximum 4
         * @nullable
         */
      group_type_index?: number | null;
      /** Abbreviate large numbers (e.g. 10,000 → 10K). Only applies to numeric properties. */
      is_big_number?: boolean;
      /** True when PostHog writes this property itself. Its name and display type are fixed — an update changing either is rejected. */
      readonly is_canonical?: boolean;
      /**
         * For select properties: the allowed options. Required (non-empty) when display_type is 'select'; cleared server-side for other types.
         * @nullable
         */
      options?: CustomPropertyOption[] | null;
      /** The data-warehouse view-sync binding feeding this property, or null when values are set manually. */
      readonly source?: CustomPropertySource | null;
      readonly created_at?: string;
      /** @nullable */
      readonly created_by?: number | null;
      /** @nullable */
      readonly updated_at?: string | null;
      /** Workflows that use this property, resolved by definition id. */
      readonly references?: readonly CustomPropertyReference[];
    }

