    /**
     * `SignalScoutNote` projection used by `notes-list` and `notes-create`.
     */
    export interface ScoutNote {
      /** Note UUID. Pass to `scout-notes-delete` to retire the note. */
      id: string;
      /** Target scout skill (`signals-scout-*`), or blank for a general note addressed to every scout on the fleet. */
      skill_name: string;
      /** The note's prose, read verbatim by scout runs. */
      content: string;
      /**
         * ISO-8601 creation timestamp.
         * @nullable
         */
      created_at: string | null;
      /**
         * ISO-8601 expiry, or null for a note that stays active until deleted.
         * @nullable
         */
      expires_at: string | null;
      /**
         * Display name of the user who left the note, or null when unavailable.
         * @nullable
         */
      created_by_name: string | null;
      /** Where the note came from. `human` for one left directly through this API. `report_dismissal` for one forwarded from the note someone typed when they dismissed, snoozed, or restored one or more inbox reports: one reviewer's verdict on the reports its content names, so weigh it as evidence about those reports rather than as fleet-level steering. `report_discussion` for the question someone asked when they opened a discussion on a report: context to weigh, neither a verdict on the report nor a directive. `report_feedback` for the note someone left when rating a report useful or not: one reader's rating of the named report, context to weigh rather than a directive. */
      origin: string;
    }

    /**
     * Request body for `notes-create`.
     */
    export interface ScoutNoteCreateRequest {
      /**
         * The note's prose — feedback, a pointer, or a nudge for the scout(s) to weigh on their next runs (e.g. 'we shipped a new checkout on Tuesday, watch conversion closely', 'stop flagging the staging traffic spike'). Write it in Markdown; scouts read it verbatim.
         * @maxLength 10000
         */
      content: string;
      /**
         * Address the note to one scout by its skill name (`signals-scout-*`, exact match against an existing scout skill on the project — check `scout-config-list` for the roster). Omit or leave blank for a general note every scout sees.
         * @maxLength 200
         */
      skill_name?: string;
      /**
         * Optional ISO-8601 expiry. After this time the note drops out of the default list view, so time-boxed steering ('watch closely this week') retires itself. Omit for a note that stays active until deleted.
         * @nullable
         */
      expires_at?: string | null;
    }

    /**
     * One report a scanner's scout filed. Enough to read it in Replay Vision; the inbox owns the
     * full record (status, priority, reviewers, run trail).
     */
    export interface ScoutReport {
      /** The report's id, as used by the Signals inbox. */
      report_id: string;
      /** The scout that filed it, as its skill name. */
      skill_name: string;
      /** When the run that filed this report started. Later edits do not move it. */
      filed_at: string;
      /** The report's title. Empty when the scout left it unset. */
      title: string;
      /** The report body, as markdown. Empty when the scout left it unset. */
      summary: string;
      /** Charts the scout attached. The summary places one inline with a `[label](chart:<chart_id>)` link; any it does not place render after the body. */
      charts: ReportChart[];
    }

    /**
     * Request body for the batched emissions / emission-reports lookups: the set of run UUIDs to
     * resolve in one call. Collapses the findings UI's old per-run fan-out (one request — and for the
     * reports lookup, one ClickHouse round-trip — per emitted run) into a single request.
     */
    export interface ScoutRunIdsBatchRequest {
      /**
         * UUIDs of the `SignalScoutRun` rows to resolve in one batch. Run ids belonging to another team are silently ignored (they contribute no rows) rather than failing the whole request. Capped at 200 ids per call.
         * @maxItems 200
         */
      run_ids: string[];
    }

    /**
     * `SignalScratchpad` projection used by `search-memory` and `remember`.
     */
    export interface ScratchpadEntry {
      /** Agent-chosen semantic key, unique per team. */
      key: string;
      /** Prose content for prompt injection. Blank when the search projected it out (`keys_only=true`); truncated to a preview when `content_max_chars` was set. */
      content: string;
      /**
         * ISO-8601 creation timestamp.
         * @nullable
         */
      created_at: string | null;
      /**
         * ISO-8601 last-write timestamp.
         * @nullable
         */
      updated_at: string | null;
      /**
         * ISO-8601 expiry, or null for a durable memory that stays until it's forgotten.
         * @nullable
         */
      expires_at?: string | null;
      /**
         * Run that wrote this entry, or null if human-authored.
         * @nullable
         */
      created_by_run_id: string | null;
      /**
         * Canonical skill name of the scout that created this entry (e.g. `signals-scout-apm`), or null if human-authored.
         * @nullable
         */
      created_by_skill?: string | null;
      /**
         * Relative Tasks UI deep-link to the run that created this entry, or null if the run linkage isn't captured.
         * @nullable
         */
      created_by_run_url?: string | null;
    }

    /**
     * * `none` - none
     * * `warning` - warning
     * * `danger` - danger
     */
    export type SdkAssessmentSeverityEnum = typeof SdkAssessmentSeverityEnum[keyof typeof SdkAssessmentSeverityEnum];


    export const SdkAssessmentSeverityEnum = {
      None: 'none',
      Warning: 'warning',
      Danger: 'danger',
    } as const;

    export interface SdkReleaseAssessment {
      /** In-use SDK version string, e.g. '1.298.0'. */
      version: string;
      /** Number of events captured with this version in the last 7 days. */
      count: number;
      /** Timestamp of the most recent event seen for this version (ISO 8601). */
      max_timestamp: string;
      /**
         * When this version was published on GitHub (ISO 8601), or null if unknown.
         * @nullable
         */
      release_date: string | null;
      /**
         * Days since this version was released, or null if unknown.
         * @nullable
         */
      days_since_release: number | null;
      /**
         * Human-readable relative release age matching the UI (e.g. '5 months ago'). Null when release_date is unknown.
         * @nullable
         */
      released_ago: string | null;
      /** True when this version is flagged as outdated by smart-semver rules. */
      is_outdated: boolean;
      /** True when this version is flagged as old by age alone (separate from semver rules). */
      is_old: boolean;
      /** True if is_outdated OR is_old. */
      needs_updating: boolean;
      /** True when this version equals or exceeds the latest known published version. */
      is_current_or_newer: boolean;
      /** Per-version badge tooltip text matching the SDK Health UI exactly. Quote verbatim when reporting to users. Varies by state: 'Released X ago. Upgrade recommended.' for outdated versions, 'You have the latest available.' for current versions, or 'Released X ago. Upgrading is a good idea, but it's not urgent yet.' for recent-but-behind versions. */
      status_reason: string;
      /** SQL SELECT statement for drilling into events for this SDK version over the last 7 days. Suitable to pass to the execute-sql tool or to display as a copy-paste snippet. */
      sql_query: string;
      /** Relative URL path (starting with /project/{id}/) for the Activity > Explore page pre-filtered to events captured with this lib and lib_version over the last 7 days. Combine with the user's PostHog host (e.g. us.posthog.com) for a clickable link. */
      activity_page_url: string;
    }

    export interface SdkAssessment {
      /** SDK identifier, e.g. 'web', 'posthog-python', 'posthog-node', 'posthog-ios'.
       *
       * * `web` - web
       * * `posthog-ios` - posthog-ios
       * * `posthog-android` - posthog-android
       * * `posthog-java` - posthog-java
       * * `posthog-server` - posthog-server
       * * `posthog-node` - posthog-node
       * * `posthog-python` - posthog-python
       * * `posthog-php` - posthog-php
       * * `posthog-ruby` - posthog-ruby
       * * `posthog-go` - posthog-go
       * * `posthog-flutter` - posthog-flutter
       * * `posthog-react-native` - posthog-react-native
       * * `posthog-kmp` - posthog-kmp
       * * `posthog-dotnet` - posthog-dotnet
       * * `posthog-elixir` - posthog-elixir */
      lib: LibEnum;
      /** Human-readable SDK name matching the SDK Health UI (e.g. 'Python', 'Node.js', 'Web', 'iOS'). */
      readable_name: string;
      /** Most recent published version of this SDK. */
      latest_version: string;
      /** True if this SDK needs attention (is_outdated OR is_old). */
      needs_updating: boolean;
      /** True if the primary in-use version is flagged as outdated. */
      is_outdated: boolean;
      /** True if the primary in-use version is flagged as old by age alone. */
      is_old: boolean;
      /** True when this SDK must be replaced by a supported successor rather than upgraded in place. */
      migration_required: boolean;
      /** UI severity badge — 'none' when healthy, 'warning' when outdated, 'danger' when the majority of team SDKs are outdated.
       *
       * * `none` - none
       * * `warning` - warning
       * * `danger` - danger */
      severity: SdkAssessmentSeverityEnum;
      /** Per-SDK programmatic summary (used for ranking/filtering). For user-facing copy, prefer releases[].status_reason (badge tooltip) and banners (top-level alert text) — those match the UI exactly. */
      reason: string;
      /** Top-level alert sentences matching the SDK Health UI's 'Time for an update!' banner — one per outdated version with significant traffic. Quote verbatim when surfacing the headline to users. */
      banners: string[];
      /** Per-version assessment for all versions seen in the last 7 days. */
      releases: SdkReleaseAssessment[];
      /** Outdated versions that handle a significant share of traffic (above the threshold). Not populated for mobile SDKs. */
      outdated_traffic_alerts: OutdatedTrafficAlert[];
    }

