    /**
     * Population filter for training examples. Use {} for all identified users.
     */
    export type ValidatePipelineRequestTrainingPopulation = { [key: string]: unknown };

    /**
     * Population filter for daily scoring. Defaults to training_population if not provided.
     */
    export type ValidatePipelineRequestInferencePopulation = { [key: string]: unknown };

    export interface ValidatePipelineRequest {
      /** Event name to predict, e.g. '$pageview'. Must exist in the team's event schema. Omit when predicting an action target (pass target_definition instead). */
      target_event?: string;
      /** Optional target definition. Pass {"type": "action", "action_id": N} to predict a PostHog action (multi-step / property / autocapture matcher) instead of a single event. */
      target_definition?: unknown;
      /**
         * Predict whether the target event occurs within this many days.
         * @minimum 1
         * @maximum 365
         */
      horizon_days?: number;
      /**
         * How far back to look for training examples. Default: 180.
         * @minimum 7
         * @maximum 730
         */
      training_lookback_days?: number;
      /** Population filter for training examples. Use {} for all identified users. */
      training_population?: ValidatePipelineRequestTrainingPopulation;
      /** Population filter for daily scoring. Defaults to training_population if not provided. */
      inference_population?: ValidatePipelineRequestInferencePopulation;
    }

    export interface ValidationWarning {
      /** Machine-readable warning code, e.g. 'low_volume' or 'extreme_imbalance'. */
      code: string;
      /** Human-readable warning description. */
      message: string;
      /** Severity level. 'error' blocks creation; 'warning' requires acknowledgement.
       *
       * * `info` - info
       * * `warning` - warning
       * * `error` - error */
      severity: IngestionWarningSeverityEnum;
    }

    export interface ValidatePipelineResponse {
      /** True if the pipeline definition is valid and training can start. */
      can_proceed: boolean;
      /** True if there are non-blocking warnings the user should acknowledge before proceeding. */
      requires_acknowledgement: boolean;
      /**
         * Estimated number of user-level training rows based on the population and lookback window.
         * @nullable
         */
      estimated_training_rows: number | null;
      /**
         * Estimated number of positive examples (users who performed the target event).
         * @nullable
         */
      positive_count: number | null;
      /**
         * Estimated number of negative examples.
         * @nullable
         */
      negative_count: number | null;
      /**
         * Fraction of the training population that performed the target event.
         * @nullable
         */
      base_rate: number | null;
      /**
         * Estimated number of users in the inference (daily scoring) population.
         * @nullable
         */
      inference_population_size: number | null;
      /** List of validation warnings. Check 'severity' — 'error' blocks creation. */
      warnings: ValidationWarning[];
      /**
         * Internal error message if validation itself failed to run.
         * @nullable
         */
      error: string | null;
    }

    export interface ViewLinkValidation {
      /**
         * Name of the table or view being joined onto the source table.
         * @maxLength 255
         */
      joining_table_name: string;
      /**
         * Column or HogQL expression on the joining table used as the join key.
         * @maxLength 255
         */
      joining_table_key: string;
      /**
         * Name of the table the join starts from, for example events.
         * @maxLength 255
         */
      source_table_name: string;
      /**
         * Column or HogQL expression on the source table used as the join key.
         * @maxLength 255
         */
      source_table_key: string;
    }

    export interface ViewLinkValidationError {
      /**
         * Request field the error relates to, if any.
         * @nullable
         */
      attr: string | null;
      /** Machine-readable error code, for example QueryError. */
      code: string;
      /** Why the join failed to validate. */
      detail: string;
      /** Error category; always query_error for validation failures. */
      type: string;
      /**
         * The HogQL statement that failed to validate.
         * @nullable
         */
      hogql: string | null;
    }

    export interface ViewLinkValidationResponse {
      /** Whether the join compiled and returned rows when executed against a sample of the source table. */
      is_valid: boolean;
      /**
         * Warning about the validation result, for example when the sampled join returned no rows.
         * @nullable
         */
      msg: string | null;
      /**
         * The HogQL statement used to validate the join.
         * @nullable
         */
      hogql: string | null;
      /** Column names for each row in results. */
      columns: string[];
      /** Distinct source and joining key pairs from the joined result, at most 5. */
      results: unknown[][];
      /**
         * Number of sampled source rows checked for a join match, at most 10000. Null when the match-rate query failed.
         * @nullable
         */
      total_rows: number | null;
      /**
         * Number of sampled source rows with at least one match in the joining table. Null when the match-rate query failed.
         * @nullable
         */
      matched_rows: number | null;
      /**
         * matched_rows divided by total_rows, between 0 and 1. Null when the match-rate query failed or no rows were sampled.
         * @nullable
         */
      match_rate: number | null;
    }

    /**
     * Full run detail: the list fields plus the synthesized report and the recordings it summarized.
     */
    export interface VisionActionRun {
      readonly id: string;
      /** Run outcome: running, completed, failed, or skipped.
       *
       * * `running` - Running
       * * `completed` - Completed
       * * `failed` - Failed
       * * `skipped` - Skipped */
      readonly status: VisionActionRunStatusEnum;
      /**
         * The scheduled fire time this run was claimed for.
         * @nullable
         */
      readonly scheduled_at: string | null;
      /** Number of observations that fed this run's summary. */
      readonly observation_count: number;
      /**
         * Short human-readable reason a run skipped or failed; null on success.
         * @nullable
         */
      readonly error_reason: string | null;
      /** True for the run recording an alert's condition clearing after a breach (the recovery bookend in run history). False for alert firings and summaries. */
      readonly is_recovery: boolean;
      readonly created_at: string;
      readonly updated_at: string;
      /** The synthesized group-summary report in Markdown. Empty until a run completes successfully. */
      readonly synthesized_markdown: string;
      /** Recordings this run included in its summary, in summary order. Empty for runs recorded before this was tracked, and for skipped/failed runs. */
      readonly observations: readonly RunObservation[];
    }

    export interface VisionQuota {
      /**
         * Credits the org may spend per billing period (1 credit = $0.01). Null when billing has synced the product with no spend limit: uncapped.
         * @nullable
         */
      readonly credit_limit: number | null;
      /** Credits spent this period: succeeded observations from the receipt ledger plus reserved in-flight observations. */
      readonly credits_used: number;
      /**
         * `credit_limit - credits_used`, floored at 0. Null when uncapped.
         * @nullable
         */
      readonly remaining: number | null;
      /** True when `credits_used >= credit_limit`; further observations are skipped until next period. Always false when uncapped. */
      readonly exhausted: boolean;
      /** First moment of the current quota period (UTC). */
      readonly period_start: string;
      /** First moment of the next quota period (UTC); the current period's exclusive upper bound. */
      readonly period_end: string;
      /** `scanners_monthly_credits` plus `backfills_committed_credits`. Kept as the single headline number; prefer the two components when pro-rating, since only the scanner half is a monthly rate. */
      readonly projected_monthly_credits: number;
      /** Credit-weighted sum of enabled scanners' projected observations/month across the organization. A monthly rate: only the part falling in the days left of the period lands this period. Scanners without a computed estimate contribute 0. */
      readonly scanners_monthly_credits: number;
      /** Committed-but-unspent credits of the organization's active backfills. A one-off charge rather than a rate, so it lands in full regardless of how much of the period is left. */
      readonly backfills_committed_credits: number;
      /** Credits per period included for free. Already counted inside `credit_limit`; only credits beyond this number are billed. */
      readonly free_monthly_credits: number;
    }

    export interface WarehouseConnection {
      /** Connection host — the warehouse name is the SNI subdomain, e.g. my-warehouse.dw.us.postwh.com */
      host: string;
      /** Postgres wire-protocol port */
      port: number;
      /** Database to connect to — always 'ducklake' */
      database: string;
      /** Root database username */
      username: string;
    }

    /**
     * * `pending` - pending
     * * `provisioning` - provisioning
     * * `ready` - ready
     * * `failed` - failed
     * * `deleting` - deleting
     * * `deleted` - deleted
     */
    export type WarehouseStatusResponseStateEnum = typeof WarehouseStatusResponseStateEnum[keyof typeof WarehouseStatusResponseStateEnum];


    export const WarehouseStatusResponseStateEnum = {
      Pending: 'pending',
      Provisioning: 'provisioning',
      Ready: 'ready',
      Failed: 'failed',
      Deleting: 'deleting',
      Deleted: 'deleted',
    } as const;

    export interface WarehouseStatusResponse {
      /** duckgres org identifier (the PostHog organization id) */
      org_id: string;
      /** Overall provisioning lifecycle state
       *
       * * `pending` - pending
       * * `provisioning` - provisioning
       * * `ready` - ready
       * * `failed` - failed
       * * `deleting` - deleting
       * * `deleted` - deleted */
      state: WarehouseStatusResponseStateEnum;
      /** Human-readable detail for the current state */
      status_message: string;
      /** Object-store sub-resource provisioning state */
      s3_state: string;
      /** Metadata-store sub-resource provisioning state */
      metadata_store_state: string;
      /** Worker identity sub-resource provisioning state */
      identity_state: string;
      /** Credentials sub-resource provisioning state */
      secrets_state: string;
      /**
         * When the warehouse became ready
         * @nullable
         */
      ready_at: string | null;
      /**
         * When provisioning failed
         * @nullable
         */
      failed_at: string | null;
      connection?: WarehouseConnection | null;
      /** Whether this project already has a warehouse backfill configured. When true, its table name is fixed and the enable form should not be shown. */
      has_backfill: boolean;
      /**
         * This project's per-environment table suffix (events_<suffix>). Null when the project still writes to the shared tables.
         * @nullable
         */
      table_suffix: string | null;
      /** Whether this project is onboarded onto the managed warehouse. False when the warehouse exists but this project has not picked a schema yet — show the onboarding screen in that case. */
      team_onboarded: boolean;
      /**
         * Schema this project's data lands in. Null when the project is not onboarded.
         * @nullable
         */
      schema_name: string | null;
    }

    /**
     * Request body for warming a full idling Run while composing a Code-app cloud task.
     *
     * Collection-level: no task exists yet at typing time. The warmer births a draft Task and an
     * interactive Run that boots and starts the agent, optionally cloning and checking out a repository,
     * then idles awaiting the first message. `github_integration` is a plain integration PK (an integer);
     * the view re-scopes it to the caller's team before use.
     */
    export interface WarmTaskRequest {
      /**
         * Optional GitHub repository to clone, in `organization/repo` format (e.g. `posthog/posthog`).
         * @maxLength 255
         * @nullable
         */
      repository?: string | null;
      /**
         * GitHub repositories to clone into the warm sandbox, each in `organization/repo` format.
         * @maxItems 3
         * @items.maxLength 255
         */
      repositories?: string[];
      /**
         * Primary key of the team's GitHub integration to clone with when a repository is selected.
         * @nullable
         */
      github_integration?: number | null;
      /**
         * Branch to check out in the warm sandbox. Defaults to the repository's default branch when omitted.
         * @maxLength 255
         * @nullable
         */
      branch?: string | null;
      /** Agent runtime adapter to warm the sandbox on ('claude' or 'codex'). The warm Run starts the agent on this runtime so a matching submit reuses it; a submit selecting a different runtime falls through to a cold Run instead of reusing a mismatched warm session.
       *
       * * `claude` - claude
       * * `codex` - codex */
      runtime_adapter?: RuntimeAdapterEnum | null;
      /**
         * LLM model identifier to warm the sandbox on. A submit selecting a different model won't reuse this warm Run.
         * @nullable
         */
      model?: string | null;
      /** Reasoning effort to warm the sandbox on for models that expose an effort control.
       *
       * * `low` - low
       * * `medium` - medium
       * * `high` - high
       * * `xhigh` - xhigh
       * * `max` - max
       * * `ultracode` - ultracode */
      reasoning_effort?: ReasoningEffortEnum | null;
      /**
         * Optional sandbox environment to provision before the task is submitted.
         * @nullable
         */
      sandbox_environment_id?: string | null;
      /**
         * Optional custom base image to provision before the task is submitted; takes precedence over the environment's image.
         * @nullable
         */
      custom_image_id?: string | null;
    }

    /**
     * Response for a successful warm request — the draft Task + idling warm Run reused on submit.
     */
    export interface WarmTaskResponse {
      /** Id of the draft Task birthed for the warm Run. */
      task_id: string;
      /** Id of the idling warm Run. The normal create+run path reuses and activates it on submit. */
      run_id: string;
    }

